```javascript
let target = "1234"; // The target PIN
let alphabet = "0123456789"; // The characters to use for the bruteforce
let attempts = []; // An array to store the attempted PINs

// Function to bruteforce the PIN
function bruteforce(target, alphabet, attempts) {
  for (let i = 0; i < alphabet.length; i++) {
    for (let j = 0; j < alphabet.length; j++) {
