    xmin=-1, xmax=5,
    ymin=-1, ymax=5,
    enlargelimits={abs=0.5},
    axis line style={latex-latex},
    tick label style={font=\small},
    xmajorgrids,
    ymajorgrids,
    grid style={gray!30},
    clip=false,
    ]

\addplot [only marks, mark=*, mark options={fill=black}] coordinates {
    (1,1) coordinate (x) as $x$,
    (2,3) coordinate (y1) as $y_1$,
    (3,2) coordinate (y2) as $y_2$,
    (4,4) coordinate (y3) as $y_3$,
};

\draw [dashed, gray] (x |- 0,0) -- (x |- 0,axis cs:axis description cs:1.2,1.2);
\draw [dashed, gray] (x -| 0,0) -- (x -| axis cs:axis description cs:1.2,1.2);

\fill [paleRed!20] (x-axis cs:1.2,0) rectangle (axis cs:5,5);
\node at (x) [above left] {$x$};
\node at (y1) [above right] {$y_1$};
\node at (y2) [below right] {$y_2$};
\node at (y3) [above left] {$y_3$};
\end{axis}
\end{tikzpicture}

\end{document}
```

This code creates a 2D plot with the point $x$ and three other points $y_1$, $y_2$, and $y_3$. The region to the top right of $x$ is shaded pale red, and axis-parallel dashed lines go through the point $x$. The plot uses professional-looking colors and styles.

